svg.script:
(function(){
 var items=document.querySelectorAll('.municipality--interactive');
 items.forEach(function(item){
   function activate(){
     items.forEach(function(other){other.classList.remove('is-active')});
     item.classList.add('is-active');
     item.dispatchEvent(new CustomEvent('municipality-select',{bubbles:true,detail:{
       municipality:item.getAttribute('data-municipality'),
       ine:item.getAttribute('data-ine'),
       label:item.getAttribute('aria-label')
     }}));
   }
   item.addEventListener('click',activate);
   item.addEventListener('keydown',function(e){
     if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}
   });
 });
})();
